#[cfg(test)]
mod alias_pi_interaction_controls {
 use super::*;
 fn fixture()->(IdTable<ExprId,Expr>,IdTable<LevelId,Level>,Environment){let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();l.insert(LevelId(1),Level::Succ(LevelId(0))).unwrap();for(id,x)in[(0,Expr::Sort(LevelId(1))),(1,Expr::BVar(0)),(2,Expr::Lam{domain:ExprId(1),body:ExprId(1)}),(3,Expr::Lam{domain:ExprId(0),body:ExprId(2)}),(4,Expr::BVar(1)),(5,Expr::BVar(2))]{e.insert(ExprId(id),x).unwrap();}(e,l,Environment::empty())}
 fn alias(c:&TypeChecker<'_>,index:u64)->Closure{let mut frame=EnvFrame::empty().extend(c.closure(ExprId(3),EnvFrame::empty()));for n in 0..index{frame=frame.extend_free(FreeId(90+n));}c.closure(match index{0=>ExprId(1),1=>ExprId(4),_=>ExprId(5)},frame)}
 #[test]fn short_alias_to_dependent_function_reuses_completed_pi(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);for index in [0,1]{let t=alias(&c,index);let first=c.infer_exact_closure_in_context(&t,&[],&mut 4096,0);assert!(matches!(first,Some(TypeValue::Pi{..})));let mut work=1;assert_eq!(c.infer_exact_closure_in_context(&t,&[],&mut work,0),first);assert_eq!(work,0);}}
 #[test]fn changed_capture_zero_work_and_unadmitted_aliases_never_reuse_pi(){let _scope=crate::run_flags::enter();let(e,l,env)=fixture();let mut c=TypeChecker::new(&e,&l,&env);let t=alias(&c,0);assert!(c.infer_exact_closure_in_context(&t,&[],&mut 4096,0).is_some());assert!(c.infer_exact_closure_in_context(&t,&[],&mut 0,0).is_none());let changed=Closure::with_levels(t.expr,EnvFrame::empty().extend(c.closure(ExprId(0),EnvFrame::empty())),t.levels.clone());assert!(c.infer_exact_closure_in_context(&changed,&[],&mut 1,0).is_none());let wide=alias(&c,2);assert!(c.infer_exact_closure_in_context(&wide,&[],&mut 4096,0).is_some());assert!(c.infer_exact_closure_in_context(&wide,&[],&mut 1,0).is_none());c.strict_origin_probe=true;assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());}
}
